#!/usr/bin/env python3
"""Model Bayesian stok beras total per provinsi per bulan (Jan 2024 – Sep 2026), dalam SATU file.

File ini memuat (1) hasil model yang sudah dihitung, sehingga hasilnya bisa langsung dilihat tanpa menjalankan
model lagi, dan (2) seluruh kode untuk membuat ulang hasil itu dari data mentah.

HASIL (sudah dihitung; 4 rantai x 1.000 draw, 0 divergensi, r-hat maks 1,06)
---------------------------------------------------------------------------
Stok nasional akhir September 2026, skenario dasar (juta ton; median dan interval 90%):
  Total                     14,21   (11,31–18,61)
  BULOG                      4,65   (4,29–5,04)
  Swasta (di luar BULOG)     9,57   (6,74–14,01)
    rumah tangga             7,59   (5,15–11,39)
    pedagang                 0,91   (0,30–2,18)
    penggilingan             0,50   (0,09–1,50)
    horeka & industri        0,26   (0,02–1,08)

Stok nasional total per kuartal (juta ton):
  2024-03  total   9,17 (7,59–11,39)   BULOG 2,24
  2024-06  total  11,39 (9,75–13,74)   BULOG 2,69
  2024-09  total  12,80 (11,05–15,29)   BULOG 2,19
  2024-12  total  11,38 (9,47–14,07)   BULOG 1,99
  2025-03  total  11,64 (9,68–14,50)   BULOG 2,47
  2025-06  total  13,50 (11,41–16,58)   BULOG 4,13
  2025-09  total  14,42 (12,11–17,73)   BULOG 4,19
  2025-12  total  12,06 (9,59–15,66)   BULOG 3,37
  2026-03  total  12,92 (10,36–16,77)   BULOG 4,31
  2026-06  total  13,91 (11,21–18,00)   BULOG 5,52
  2026-09  total  14,21 (11,31–18,61)   BULOG 4,65

Per pulau, akhir September 2026 (juta ton):
  Jawa                    7,36 (5,90–9,29)   BULOG 2,42   swasta 4,93
  Sumatera                3,08 (2,21–4,34)   BULOG 1,12   swasta 1,97
  Sulawesi                1,50 (0,94–2,77)   BULOG 0,52   swasta 0,99
  Bali & Nusa Tenggara    0,88 (0,65–1,16)   BULOG 0,28   swasta 0,60
  Kalimantan              0,81 (0,64–1,06)   BULOG 0,19   swasta 0,62
  Maluku & Papua          0,47 (0,32–0,81)   BULOG 0,09   swasta 0,39

Uji sensitivitas, stok nasional akhir Sep 2026 menurut kendala "stok swasta tidak negatif":
  per pulau (dasar)     14,2 (11,3–18,6)
  nasional saja         14,2 (11,4–19,1)
  per provinsi          16,8 (14,0–21,3)

Validasi: survei SSBAT Des 2022 (4,06 juta ton) disembunyikan; tebakan model 4,40 (3,44–5,59).

CARA PAKAI
----------
Lihat hasil (instan; hanya butuh Python 3, tanpa data mentah, tanpa PyMC):
    python stok_beras_satu_file.py                       # ringkasan nasional, pulau, provinsi, uji model
    python stok_beras_satu_file.py --bulan 2025-12       # bulan lain
    python stok_beras_satu_file.py --wilayah "JAWA TIMUR"   # deret bulanan satu provinsi atau pulau
    python stok_beras_satu_file.py --excel hasil.xlsx    # tabel lengkap ke Excel (butuh pandas + openpyxl)
    python stok_beras_satu_file.py --csv hasil.csv       # semua angka posterior ke CSV
    python stok_beras_satu_file.py --grafik stok.svg     # grafik stok nasional (SVG, buka di browser)

Jalankan ulang seluruh model dari data mentah (butuh pandas, numpy, openpyxl, pymc, opsional nutpie; ±10 menit/run):
    BPS_API_KEY=... python stok_beras_satu_file.py --jalankan-ulang Non_PAW_dari_nol.xlsm --folder kerja
    opsi tambahan: --holdout 2022-12 (validasi), --positif provinsi|pulau|nasional (uji sensitivitas),
                   --draws 1000 --tune 1000 --chains 4

DATA YANG DIPAKAI
-----------------
- INATRADE: sheet "2024-2026" di Non_PAW_dari_nol.xlsm, semua baris Jenis Komoditi = Beras (PAW + Non PAW);
  laporan kg dikoreksi ke ton; kode 00372 = BULOG (dipisah dari pedagang).
- BPS WebAPI: produksi padi KSA (var 2506 bulanan 2025–2026, 1498 tahunan s.d. 2024), konsumsi beras Susenas
  per kab/kota (2094) x penduduk (2790), harga beras penggilingan (500, 2277).
- Angka publik (JANGKAR_PUBLIK_CSV di bawah, dengan sumbernya): survei stok (SCBN BPS Jun 2022; SSBAT
  Bapanas-BPS Des 2022 & Des 2023), stok BULOG, impor, konsumsi dan neraca Bapanas.

MODEL (ringkas; rincian di docstring bagian MODEL)
--------------------------------------------------
Neraca per provinsi per bulan: stok = stok bulan lalu + produksi x (1 - susut) + impor + masuk - keluar
- konsumsi; tiap sumber data dihubungkan lewat persamaan pengukuran dengan bias dan noise sendiri; stok total
provinsi dan stok swasta per pulau tidak boleh negatif. Angka per komponen swasta dan BULOG per provinsi
adalah alokasi model, bukan data.
"""
