# (uji, periode survei, sumber, amatan, prediksi median, p05, p95, dipakai untuk fit)
VALIDASI = [('validasi (Des 2022 disembunyikan)', '2022-06', 'survei_bps_scbn', 9.71, 9.73, 8.69, 10.916, 'ya'), ('validasi (Des 2022 disembunyikan)', '2022-12', 'survei_bapanas', 4.06, 4.397, 3.435, 5.59, 'tidak (disembunyikan)'), ('validasi (Des 2022 disembunyikan)', '2023-12', 'survei_bapanas', 4.13, 4.228, 3.77, 4.76, 'ya'), ('fit penuh', '2022-06', 'survei_bps_scbn', 9.71, 9.706, 8.709, 10.912, 'ya'), ('fit penuh', '2022-12', 'survei_bapanas', 4.06, 4.099, 3.678, 4.585, 'ya'), ('fit penuh', '2023-12', 'survei_bapanas', 4.13, 4.195, 3.753, 4.7, 'ya')]

# (parameter, mean, batas bawah 90%, batas atas 90%, r_hat) — skenario dasar
PARAMETER = [('susut', 0.0713, 0.0434, 0.0935, 1.011), ('log_1_plus_nu', 0.3413, 0.3072, 0.3749, 1.011), ('dev_tahunan_nu[0]', -0.0195, -0.0674, 0.0292, 1.004), ('dev_tahunan_nu[1]', -0.0114, -0.0405, 0.02, 1.011), ('dev_tahunan_nu[2]', -0.0621, -0.1032, -0.0218, 1.002), ('dev_tahunan_nu[3]', -0.0106, -0.0505, 0.0277, 1.001), ('dev_tahunan_nu[4]', 0.0036, -0.042, 0.048, 1.001), ('sigma_proses', 0.0424, 0.0036, 0.1014, 1.0), ('stok_awal_nasional', 10455273.206, 8570104.3379, 12636716.1279, 1.007), ('tau_theta', 0.0404, 0.0026, 0.1103, 1.015), ('sigma_bulog', 0.2428, 0.1758, 0.3268, 1.065), ('bias_bulog_inatrade', -0.0913, -0.151, -0.0327, 1.001), ('bias_survei[0]', -0.6782, -0.9068, -0.4623, 1.004), ('bias_survei[1]', -0.0649, -0.2682, 0.1325, 1.006), ('mu_a', -8.6272, -9.5571, -7.6708, 1.032), ('tau_a', 1.1205, 0.5766, 1.8944, 1.018), ('sd_inatrade', 0.4392, 0.3641, 0.5174, 1.006), ('c_harga', 0.1005, 0.0396, 0.1613, 1.002), ('beta_harga', -0.1641, -0.3342, 0.0079, 1.002), ('sd_harga', 0.1127, 0.0744, 0.1646, 1.001), ('pangsa_komponen[0]', 0.7962, 0.6699, 0.9019, 1.0), ('pangsa_komponen[1]', 0.0614, 0.01, 0.146, 1.0), ('pangsa_komponen[2]', 0.1045, 0.0322, 0.2075, 1.0), ('pangsa_komponen[3]', 0.0379, 0.0022, 0.106, 1.001)]

KOMPONEN = [('total', 'Total'), ('bulog', 'BULOG'), ('swasta', 'Swasta (di luar BULOG)'),
            ('rumah_tangga', 'Rumah tangga'), ('pedagang', 'Pedagang'), ('penggilingan', 'Penggilingan'),
            ('horeka', 'Horeka & industri')]
BLN = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des']


def muat_hasil():
    """Baris hasil sebagai list of dict (angka sudah float)."""
    teks = gzip.decompress(base64.b64decode(''.join(HASIL_GZ_B64.split()))).decode()
    rows = list(csv.DictReader(io.StringIO(teks)))
    for r in rows:
        for k in ('median', 'p05', 'p95'):
            r[k] = float(r[k])
    return rows


def _f(v, d=2):
    return f'{v:,.{d}f}'.replace(',', '_').replace('.', ',').replace('_', '.')


def _nama_bulan(p):
    return f'{BLN[int(p[5:]) - 1]} {p[:4]}'


def laporan(rows, bulan='2026-09', wilayah=None):
    idx = {(r['skenario'], r['tingkat'], r['wilayah'], r['periode'], r['komponen']): r for r in rows}
    dasar = [r for r in rows if r['skenario'] == 'dasar']
    bulan_ada = sorted({r['periode'] for r in dasar})
    if bulan not in bulan_ada:
        sys.exit(f'Bulan {bulan} tidak ada. Pilihan: {bulan_ada[0]} s.d. {bulan_ada[-1]}')

    def g(t, w, p, k, s='dasar'):
        return idx.get((s, t, w, p, k))

    if wilayah:
        w = wilayah.strip().upper()
        cocok = {r['wilayah'] for r in dasar if r['wilayah'].upper() == w}
        if not cocok:
            semua = sorted({r['wilayah'] for r in dasar})
            sys.exit('Wilayah tidak dikenal. Pilihan: ' + ', '.join(semua))
        w = cocok.pop()
        t = next(r['tingkat'] for r in dasar if r['wilayah'] == w)
        print(f'\nStok beras {w} per bulan (juta ton, akhir bulan; median dan interval 90%)\n')
        print(f'{"Bulan":<10}{"Total":>8}{"p05":>8}{"p95":>8}{"BULOG":>8}{"Swasta":>8}')
        mx = max(g(t, w, p, 'total')['p95'] for p in bulan_ada)
        for p in bulan_ada:
            a, b, s = g(t, w, p, 'total'), g(t, w, p, 'bulog'), g(t, w, p, 'swasta')
            bar = '█' * int(round(a['median'] / mx * 30))
            print(f'{_nama_bulan(p):<10}{_f(a["median"]):>8}{_f(a["p05"]):>8}{_f(a["p95"]):>8}'
                  f'{_f(b["median"]):>8}{_f(s["median"]):>8}  {bar}')
        return

    print(f'\nSTOK BERAS INDONESIA — akhir {_nama_bulan(bulan)} (juta ton; median dan interval 90%)')
    print('=' * 78)
    for k, nm in KOMPONEN:
        r = g('nasional', 'INDONESIA', bulan, k)
        ind = '  ' if k in ('rumah_tangga', 'pedagang', 'penggilingan', 'horeka') else ''
        print(f'{ind + nm:<26}{_f(r["median"]):>8}   ({_f(r["p05"])}–{_f(r["p95"])})')
    neraca = {'2024-12': 8.4, '2025-12': 12.529, '2026-09': 17.9}
    if bulan in neraca:
        print(f'{"Pembanding: neraca Bapanas":<26}{_f(neraca[bulan]):>8}   (tanpa susut; batas atas)')

    print('\nDeret nasional (titik = median, garis = interval 90%; skala 0–20 juta ton)')
    for p in bulan_ada:
        a, b = g('nasional', 'INDONESIA', p, 'total'), g('nasional', 'INDONESIA', p, 'bulog')
        lebar = 50
        pos = lambda v: min(lebar - 1, int(round(v / 20 * (lebar - 1))))  # noqa: E731
        baris = [' '] * lebar
        for i in range(pos(a['p05']), pos(a['p95']) + 1):
            baris[i] = '─'
        baris[pos(b['median'])] = 'b'
        baris[pos(a['median'])] = '●'
        tanda = ' <' if p == bulan else ''
        print(f'  {_nama_bulan(p):<9}|{"".join(baris)}| {_f(a["median"]):>5}  BULOG {_f(b["median"])}{tanda}')
    print('  (● total, ─ interval 90%, b BULOG)')

    print(f'\nPer pulau, akhir {_nama_bulan(bulan)} (juta ton)')
    print(f'  {"Pulau":<22}{"Total":>8}{"p05":>8}{"p95":>8}{"BULOG":>8}{"Swasta":>8}')
    pul = sorted({r['wilayah'] for r in dasar if r['tingkat'] == 'pulau'},
                 key=lambda w: -g('pulau', w, bulan, 'total')['median'])
    for w in pul:
        a = g('pulau', w, bulan, 'total')
        print(f'  {w:<22}{_f(a["median"]):>8}{_f(a["p05"]):>8}{_f(a["p95"]):>8}'
              f'{_f(g("pulau", w, bulan, "bulog")["median"]):>8}{_f(g("pulau", w, bulan, "swasta")["median"]):>8}')

    print(f'\nPer provinsi, akhir {_nama_bulan(bulan)} (juta ton; diurutkan dari terbesar)')
    print(f'  {"Provinsi":<28}{"Pulau":<22}{"Total":>7}{"p05":>7}{"p95":>7}{"BULOG":>7}{"Swasta":>7}{"vs 12 bln":>10}')
    prov = sorted({(r['wilayah'], r['pulau']) for r in dasar if r['tingkat'] == 'provinsi'},
                  key=lambda x: -g('provinsi', x[0], bulan, 'total')['median'])
    lalu = f'{int(bulan[:4]) - 1}{bulan[4:]}'
    for w, pu in prov:
        a = g('provinsi', w, bulan, 'total')
        c = g('provinsi', w, lalu, 'total')
        ub = f'{round((a["median"] / c["median"] - 1) * 100) + 0:+d}%' if c and c['median'] > 0 else ''
        print(f'  {w:<28}{pu:<22}{_f(a["median"]):>7}{_f(a["p05"]):>7}{_f(a["p95"]):>7}'
              f'{_f(g("provinsi", w, bulan, "bulog")["median"]):>7}{_f(g("provinsi", w, bulan, "swasta")["median"]):>7}'
              f'{ub:>10}')

    print('\nUji model')
    for uji, per, sumber, am, me, lo, hi, dipakai in VALIDASI:
        if uji.startswith('validasi'):
            ket = '  <- disembunyikan saat fit' if dipakai.startswith('tidak') else ''
            print(f'  {sumber:<16}{_nama_bulan(per):<10} survei {_f(am)}  model {_f(me)} ({_f(lo)}–{_f(hi)}){ket}')
    print('  Sensitivitas kendala "stok swasta tidak negatif", stok nasional akhir Sep 2026:')
    for s, nm in [('dasar', 'per pulau (dasar)'), ('swasta>=0 nasional', 'nasional saja'),
                  ('swasta>=0 per provinsi', 'per provinsi')]:
        r = g('nasional', 'INDONESIA', '2026-09', 'total', s)
        print(f'    {nm:<20}{_f(r["median"], 1):>6} ({_f(r["p05"], 1)}–{_f(r["p95"], 1)})')
    print('\nParameter utama (skenario dasar)')
    lab = {'susut': 'susut (porsi produksi)', 'log_1_plus_nu': 'log(1 + porsi konsumsi non-RT)',
           'bias_survei[0]': 'bias log survei SSBAT', 'bias_survei[1]': 'bias log survei SCBN BPS',
           'beta_harga': 'elastisitas harga thd stok'}
    for nm, me, lo, hi, rh in PARAMETER:
        if nm in lab:
            print(f'  {lab[nm]:<34}{_f(me, 3):>8}  ({_f(lo, 3)} s.d. {_f(hi, 3)})')
    print()


def tulis_csv(rows, path):
    with open(path, 'w', newline='') as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0]))
        w.writeheader()
        w.writerows(rows)
    print('ditulis', path)


def tulis_excel(rows, path):
    """Excel dari hasil tertanam: Nasional, Pulau, Provinsi (format lebar), Sensitivitas, Validasi, Parameter."""
    import pandas as pd
    R = pd.DataFrame(rows)
    D = R[R.skenario == 'dasar'].rename(columns={'median': 'median_juta_ton'})
    catatan = [
        ('Isi', 'Posterior stok beras total dan per komponen, akhir bulan, Jan 2024 - Sep 2026. Satuan ribu ton.'),
        ('Interval', 'p05-p95 = interval kredibel 90% dari model Bayesian (PyMC).'),
        ('Penjumlahan', 'Median komponen tidak harus berjumlah sama dengan median total.'),
        ('Alokasi', 'BULOG per provinsi dan komponen swasta adalah alokasi model, bukan data.'),
        ('Sumber', 'Dibuat oleh stok_beras_satu_file.py dari hasil yang tertanam di file itu.'),
    ]
    with pd.ExcelWriter(path, engine='openpyxl') as W:
        pd.DataFrame(catatan, columns=['Butir', 'Keterangan']).to_excel(W, sheet_name='Catatan', index=False)
        excel_lebar(D, 'nasional').to_excel(W, sheet_name='Nasional', index=False)
        excel_lebar(D, 'pulau').rename(columns={'wilayah': 'pulau'}).to_excel(W, sheet_name='Pulau', index=False)
        excel_lebar(D, 'provinsi').rename(columns={'wilayah': 'provinsi'}).to_excel(W, sheet_name='Provinsi',
                                                                                   index=False)
        S = R[(R.tingkat == 'nasional') & R.komponen.isin(['total', 'bulog', 'swasta'])]
        S[['skenario', 'periode', 'komponen', 'median', 'p05', 'p95']].to_excel(W, sheet_name='Sensitivitas',
                                                                                index=False)
        pd.DataFrame(VALIDASI, columns=['uji', 'periode', 'sumber', 'amatan_juta_ton', 'prediksi_median',
                                        'prediksi_p05', 'prediksi_p95', 'dipakai_untuk_fit']).to_excel(
            W, sheet_name='Validasi', index=False)
        pd.DataFrame(PARAMETER, columns=['parameter', 'mean', 'p05', 'p95', 'r_hat']).to_excel(
            W, sheet_name='Parameter', index=False)
        wb = W.book
        excel_rapikan(wb['Catatan'], 1)
        wb['Catatan'].column_dimensions['B'].width = 100
        for nm, k in [('Nasional', 2), ('Pulau', 2), ('Provinsi', 3), ('Sensitivitas', 2), ('Validasi', 1),
                      ('Parameter', 1)]:
            excel_rapikan(wb[nm], k)
    print('ditulis', path)


def tulis_svg(rows, path):
    """Grafik SVG stok nasional: titik median + garis interval 90%, garis BULOG, penanda neraca Bapanas."""
    d = {(r['periode'], r['komponen']): r for r in rows
         if r['skenario'] == 'dasar' and r['tingkat'] == 'nasional'}
    per = sorted({p for p, k in d})
    W, H, L, R_, T, B = 900, 460, 60, 40, 70, 60
    x = lambda i: L + i * (W - L - R_) / (len(per) - 1)  # noqa: E731
    y = lambda v: H - B - v / 20 * (H - T - B)  # noqa: E731
    o = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" font-family="sans-serif" font-size="12">',
         f'<rect width="{W}" height="{H}" fill="white"/>',
         f'<text x="{L}" y="28" font-size="17">Stok beras nasional per bulan (juta ton, akhir bulan)</text>',
         f'<text x="{L}" y="48" fill="#555">Titik + garis tegak: total (median, interval 90%) · garis abu-abu '
         f'putus-putus: BULOG · belah ketupat: neraca Bapanas</text>']
    for v in range(0, 21, 5):
        o.append(f'<line x1="{L}" x2="{W - R_}" y1="{y(v):.1f}" y2="{y(v):.1f}" stroke="#e5e5e5"/>'
                 f'<text x="{L - 8}" y="{y(v) + 4:.1f}" text-anchor="end" fill="#555">{v}</text>')
    for i, p in enumerate(per):
        if int(p[5:]) in (1, 4, 7, 10):
            o.append(f'<text x="{x(i):.1f}" y="{H - B + 20}" text-anchor="middle" fill="#555">'
                     f'{BLN[int(p[5:]) - 1]} {p[2:4]}</text>')
    pts = ' '.join(f'{x(i):.1f},{y(d[(p, "bulog")]["median"]):.1f}' for i, p in enumerate(per))
    o.append(f'<polyline points="{pts}" fill="none" stroke="#777" stroke-width="2" stroke-dasharray="6 4"/>')
    for i, p in enumerate(per):
        a = d[(p, 'total')]
        o.append(f'<line x1="{x(i):.1f}" x2="{x(i):.1f}" y1="{y(a["p05"]):.1f}" y2="{y(a["p95"]):.1f}" '
                 f'stroke="#2563eb" stroke-opacity="0.45" stroke-width="3"/>'
                 f'<circle cx="{x(i):.1f}" cy="{y(a["median"]):.1f}" r="3.5" fill="#2563eb">'
                 f'<title>{BLN[int(p[5:]) - 1]} {p[:4]}: {_f(a["median"])} ({_f(a["p05"])}–{_f(a["p95"])})</title>'
                 f'</circle>')
    for p, v in {'2024-12': 8.4, '2025-12': 12.529, '2026-09': 17.9}.items():
        i = per.index(p)
        o.append(f'<rect x="{x(i) - 5:.1f}" y="{y(v) - 5:.1f}" width="10" height="10" fill="none" stroke="#555" '
                 f'transform="rotate(45 {x(i):.1f} {y(v):.1f})"><title>Neraca Bapanas: {_f(v)}</title></rect>')
    last = d[(per[-1], 'total')]
    o.append(f'<text x="{x(len(per) - 1) + 8:.1f}" y="{y(last["median"]) + 4:.1f}" fill="#2563eb">'
             f'{_f(last["median"], 1)}</text></svg>')
    with open(path, 'w') as f:
        f.write('\n'.join(o))
    print('ditulis', path)


